def unique(items):
    seen = []
    result = []
    for x in items:
        if x not in seen:
            seen.append(x)
            result.append(x)
    return result

print(unique([3, 1, 3, 2, 1]))

def contains(arr, target):
    if not arr:
        return False
    mid = len(arr) // 2
    if arr[mid] == target:
        return True
    if arr[mid] < target:
        return contains(arr[mid + 1:], target)
    return contains(arr[:mid], target)

print(contains(list(range(1_000_000)), 999_999))

def factorial(n):
    if n == 1:
        return 1
    return n * factorial(n - 1)

print(factorial(5))
print(factorial(0))

def total(items, i=0):
    if i == len(items):
        return 0
    return items[i] + total(items, i + 1)

